520	/// Run a closure that mutates a TOML document at `file` under the standard
521	/// write pipeline: `guard_write_path` → `with_exclusive_lock` → `read_toml` →
522	/// `f(&mut doc)` → `write_toml_with_sidecar`. Centralises what was previously
523	/// open-coded at each `Cmd::{Set,SetJson}` / `ItemsOp::{Add,Update,Remove,Apply}`
524	/// dispatch site.
525	fn mutate_doc<F>(
526	    file: &Path,
527	    allow_outside: bool,
528	    integrity: IntegrityOpts,
529	    f: F,
530	) -> Result<()>
531	where
532	    F: FnOnce(&mut TomlValue) -> Result<()>,
533	{
534	    guard_write_path(file, allow_outside)?;
535	    with_exclusive_lock(file, || {
536	        let mut doc = read_toml(file)?;
537	        f(&mut doc)?;
538	        // R3 TOCTOU narrowing: re-canonicalise target parent immediately before
539	        // the atomic persist and re-check that it still lies under `.claude/`.
540	        // Only enforced when `--allow-outside` was NOT set, since an explicit
541	        // opt-out was granted by the user in that case. This narrows (but does
542	        // not close) the window between `guard_write_path()` and `persist()`;
543	        // closing it fully requires O_NOFOLLOW via nix/rustix.
544	        if !allow_outside {
545	            recheck_claude_containment(file)?;
546	        }
547	        write_toml_with_sidecar(file, &doc, integrity)?;
548	        Ok(())
549	    })
550	}
