552	/// Re-canonicalise `file`'s parent and assert it still starts with the
553	/// `.claude/` canonical root. Used by `mutate_doc` to narrow the TOCTOU window
554	/// described in R3.
555	fn recheck_claude_containment(file: &Path) -> Result<()> {
556	    let parent = file
557	        .parent()
558	        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
559	        .unwrap_or(Path::new("."));
560	    let parent_canonical = parent
561	        .canonicalize()
562	        .with_context(|| format!("re-canonicalising parent of {} before persist", file.display()))?;
563	    let root = repo_or_cwd_root()?;
564	    let claude_dir = root.join(".claude");
565	    let claude_canonical = claude_dir.canonicalize().unwrap_or(claude_dir);
566	    if parent_canonical.starts_with(&claude_canonical) {
567	        return Ok(());
568	    }
569	    bail!(
570	        "pre-persist containment check failed: target parent {} is no longer under {} (possible TOCTOU symlink swap since guard_write_path — aborting)",
571	        parent_canonical.display(),
572	        claude_canonical.display()
573	    )
574	}
