576	/// Acquire an exclusive sidecar `.lock` file around a write operation, with a
577	/// timeout so a stranded lock (crashed tomlctl, OS-mandatory Windows lock,
578	/// heavy contention) produces a clear error instead of hanging forever.
579	///
580	/// Timeout default is 30 seconds; override with the `TOMLCTL_LOCK_TIMEOUT`
581	/// env var (integer seconds). On the first observed contention the function
582	/// emits a one-shot stderr note so a human watching the terminal knows *why*
583	/// we're paused. The retry delay carries ±20% jitter (deterministic counter
584	/// hash, no external RNG) to avoid lockstep retries between competing
585	/// processes.
586	fn with_exclusive_lock<R>(path: &Path, f: impl FnOnce() -> Result<R>) -> Result<R> {
587	    use fs4::fs_std::FileExt;
588	    use std::time::Instant;
589	
590	    let lock_path = path.with_extension(match path.extension().and_then(|s| s.to_str()) {
591	        Some(ext) => format!("{}.lock", ext),
592	        None => "lock".to_string(),
593	    });
594	    // R39: on unix, open the lock file with 0o600 so it's not world-readable.
595	    // The lock file is metadata about who holds the write mutex — no reason
596	    // for it to be group/other-readable. No-op on Windows (OpenOptionsExt is
597	    // unix-only).
598	    #[cfg(unix)]
599	    use std::os::unix::fs::OpenOptionsExt;
600	    let mut open_opts = std::fs::OpenOptions::new();
601	    open_opts
602	        .create(true)
603	        .truncate(false)
604	        .read(true)
605	        .write(true);
606	    #[cfg(unix)]
607	    open_opts.mode(0o600);
608	    let lock_file = open_opts
609	        .open(&lock_path)
610	        .with_context(|| format!("opening lock file {}", lock_path.display()))?;
611	
612	    // R25: effective timeout = env override if set, else DEFAULT_LOCK_TIMEOUT.
613	    // The error message reflects the effective timeout, not the constant default.
614	    let timeout = std::env::var("TOMLCTL_LOCK_TIMEOUT")
615	        .ok()
616	        .and_then(|s| s.parse::<u64>().ok())
617	        .map(std::time::Duration::from_secs)
618	        .unwrap_or(DEFAULT_LOCK_TIMEOUT);
619	    let base_delay_ms = LOCK_RETRY.as_millis() as u64;
620	    let start = Instant::now();
621	    let mut announced = false;
622	    let mut attempt: u64 = 0;
623	    loop {
624	        match lock_file.try_lock_exclusive() {
625	            Ok(true) => break,
626	            Ok(false) => {
627	                if !announced {
628	                    eprintln!(
629	                        "tomlctl: waiting for exclusive lock on {} …",
630	                        lock_path.display()
631	                    );
632	                    announced = true;
633	                }
634	                if start.elapsed() >= timeout {
635	                    bail!(
636	                        "lock held on {} for {} seconds — another tomlctl process may be hanging. If no tomlctl process is running, check for stale lock and delete {} manually.",
637	                        lock_path.display(),
638	                        timeout.as_secs(),
639	                        lock_path.display()
640	                    );
641	                }
642	                // ±20% jitter via a small counter hash (no RNG needed).
643	                // Hash maps attempt into [-20, 20] percent of base_delay_ms.
644	                let h = attempt
645	                    .wrapping_mul(0x9E37_79B9_7F4A_7C15)
646	                    .wrapping_add(0xD1B5_4A32_D192_ED03);
647	                let jitter_pct = (h % 41) as i64 - 20; // -20..=20
648	                let delta_ms = (base_delay_ms as i64) * jitter_pct / 100;
649	                let delay_ms = (base_delay_ms as i64 + delta_ms).max(1) as u64;
650	                std::thread::sleep(std::time::Duration::from_millis(delay_ms));
651	                attempt = attempt.wrapping_add(1);
652	            }
653	            Err(e) => {
654	                return Err(anyhow!(e)).with_context(|| {
655	                    format!("acquiring exclusive lock on {}", lock_path.display())
656	                });
657	            }
658	        }
659	    }
660	
661	    // R23: the lock_file binding is alive through this point; drop releases
662	    // the lock after `f()` returns. No explicit `let _ = lock_file;` needed.
663	    f()
664	}
