666	/// Refuse to write to files outside the current repo's `.claude/` directory
667	/// unless `--allow-outside` was passed on this invocation. Protects against
668	/// agent-influenced `artifacts.*` paths pointing at e.g. credential files.
669	///
670	/// Resolution strategy:
671	///   1. Canonicalise the target (parent if file doesn't exist yet).
672	///   2. Find the git top-level via `git rev-parse --show-toplevel`.
673	///      Fall back to CWD if git is missing or we're not inside a repo.
674	///   3. Assert canonical target lies under `<root>/.claude/`.
675	fn guard_write_path(file: &Path, allow_outside: bool) -> Result<()> {
676	    let canonical = canonicalize_for_write(file).with_context(|| {
677	        format!("canonicalising write target {}", file.display())
678	    })?;
679	
680	    let root = repo_or_cwd_root()?;
681	    let claude_dir = root.join(".claude");
682	    // Canonicalise the allowed root too so the prefix comparison is apples-to-apples
683	    // (on Windows, canonicalize yields extended-length `\\?\` paths).
684	    let claude_canonical = match claude_dir.canonicalize() {
685	        Ok(p) => p,
686	        Err(_) => claude_dir.clone(),
687	    };
688	
689	    if canonical.starts_with(&claude_canonical) {
690	        return Ok(());
691	    }
692	
693	    if allow_outside {
694	        eprintln!(
695	            "tomlctl: warning: writing outside .claude/ (path resolves to {}) — proceeding because --allow-outside was set",
696	            canonical.display()
697	        );
698	        return Ok(());
699	    }
700	
701	    bail!(
702	        "refusing to write outside .claude/ (path resolves to {}); pass --allow-outside to override",
703	        canonical.display()
704	    )
705	}
