707	/// Canonicalise a write target. If the file doesn't exist yet, canonicalise the
708	/// parent directory and re-attach the final component. Bails if neither the
709	/// file nor its parent directory exists.
710	///
711	/// R4: additionally rejects any `..` (`Component::ParentDir`) component in the
712	/// joined path. The parent canonicalises via `canonicalize()` which resolves
713	/// any embedded `..`, so a `ParentDir` in the joined result can only come from
714	/// the file-name component itself — a value like `../escape` is obviously
715	/// malicious and gets refused here even though it didn't appear after the
716	/// canonical parent prefix.
717	fn canonicalize_for_write(file: &Path) -> Result<PathBuf> {
718	    if let Ok(c) = file.canonicalize() {
719	        return Ok(c);
720	    }
721	    let parent = file
722	        .parent()
723	        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
724	        .unwrap_or(Path::new("."));
725	    let parent_canonical = parent
726	        .canonicalize()
727	        .with_context(|| format!("parent directory {} not found", parent.display()))?;
728	    let name = file
729	        .file_name()
730	        .ok_or_else(|| anyhow!("write target `{}` has no file name", file.display()))?;
731	    let joined = parent_canonical.join(name);
732	    // Reject ParentDir / RootDir components past the canonical parent prefix.
733	    // Canonicalize() normalised the prefix, so anything in `joined.components()`
734	    // after the prefix that is a `..` came from the file-name piece — refuse.
735	    let prefix_len = parent_canonical.components().count();
736	    for comp in joined.components().skip(prefix_len) {
737	        match comp {
738	            std::path::Component::ParentDir | std::path::Component::RootDir => {
739	                bail!(
740	                    "write target `{}` contains a disallowed `..` or absolute root component after canonicalisation",
741	                    file.display()
742	                );
743	            }
744	            _ => {}
745	        }
746	    }
747	    Ok(joined)
748	}
