750	/// Return the containment anchor used by `guard_write_path`.
751	///
752	/// Resolution order:
753	///   1. `TOMLCTL_ROOT` env var, if set. Canonicalised; errors if the directory
754	///      does not exist. Intended for tests, chroots, and unusual layouts where
755	///      neither the git top-level nor the CWD is the right anchor. Checked on
756	///      EVERY call so tests can swap it in/out under `env_lock()`.
757	///   2. `git rev-parse --show-toplevel` output, canonicalised. R46: memoised
758	///      in a process-lifetime `OnceLock` so repeated CLI dispatches don't fork
759	///      `git` more than once.
760	///   3. Current working directory, canonicalised. Also memoised (same cache
761	///      slot — the resolved anchor is deterministic for a given process).
762	fn repo_or_cwd_root() -> Result<PathBuf> {
763	    // Env override is always live — never cached, so a test flipping
764	    // TOMLCTL_ROOT sees the new value on the next call.
765	    if let Ok(env_root) = std::env::var("TOMLCTL_ROOT")
766	        && !env_root.is_empty()
767	    {
768	        let p = PathBuf::from(&env_root);
769	        return p.canonicalize().with_context(|| {
770	            format!("canonicalising TOMLCTL_ROOT={}", env_root)
771	        });
772	    }
773	    // R46: cache git-or-cwd resolution per process. The first call resolves
774	    // it; every subsequent call hits the OnceLock fast path.
775	    static REPO_ROOT: std::sync::OnceLock<PathBuf> = std::sync::OnceLock::new();
776	    if let Some(cached) = REPO_ROOT.get() {
777	        return Ok(cached.clone());
778	    }
779	    let cwd = std::env::current_dir().context("reading current working directory")?;
780	    let resolved = match std::process::Command::new("git")
781	        .args(["rev-parse", "--show-toplevel"])
782	        .output()
783	    {
784	        Ok(out) if out.status.success() => {
785	            let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
786	            if s.is_empty() {
787	                cwd.canonicalize().unwrap_or(cwd)
788	            } else {
789	                let p = PathBuf::from(s);
790	                p.canonicalize().unwrap_or(p)
791	            }
792	        }
793	        _ => cwd.canonicalize().unwrap_or(cwd),
794	    };
795	    // `get_or_init` ensures only the first caller's resolved path wins — a
796	    // second concurrent resolve just discards its computed value.
797	    Ok(REPO_ROOT.get_or_init(|| resolved).clone())
798	}
