800	/// Write the TOML document and (unless suppressed) also write the `<file>.sha256`
801	/// sidecar.
802	///
803	/// R31 (torn-sidecar): the hash is computed in memory from the serialised
804	/// bytes BEFORE any rename, so both tempfiles (TOML + sidecar) are staged with
805	/// byte-content that is guaranteed consistent. We then `persist()` the TOML
806	/// first and the sidecar second, both under the existing `<file>.lock`
807	/// exclusive lock. A reader that interleaves between the two `persist()`
808	/// calls either:
809	///   (a) sees the OLD TOML + OLD sidecar — hashes agree, passes integrity;
810	///   (b) sees the NEW TOML + OLD sidecar — the OLD sidecar's hash is stale,
811	///       reader fails integrity; this matches the outcome readers would see
812	///       if a writer crashed after the first persist (desired behaviour);
813	///   (c) sees the NEW TOML + NEW sidecar — hashes agree, passes integrity.
814	/// The previous hash-after-rename pipeline had a window where a reader could
815	/// observe NEW bytes but computed the hash BEFORE the sidecar was refreshed;
816	/// that window is now closed.
817	///
818	/// Failure to persist the sidecar is reported as a stderr warning but does
819	/// not fail the outer write — the primary TOML is already durable. Set
820	/// `--strict-integrity` to upgrade that warning to a hard error.
821	fn write_toml_with_sidecar(
822	    path: &Path,
823	    value: &TomlValue,
824	    integrity: IntegrityOpts,
825	) -> Result<()> {
826	    let serialized = toml::to_string_pretty(value).context("serialising TOML")?;
827	    let bytes = serialized.as_bytes();
828	
829	    if !integrity.write_sidecar {
830	        return atomic_write(path, bytes);
831	    }
832	
833	    // Stage both tempfiles with hash computed from the same in-memory bytes.
834	    let hex = hex_lower(&Sha256::digest(bytes));
835	    let sidecar = sidecar_path(path);
836	    let basename = path
837	        .file_name()
838	        .ok_or_else(|| anyhow!("target `{}` has no file name", path.display()))?
839	        .to_string_lossy()
840	        .into_owned();
841	    let sidecar_contents = format!("{}  {}\n", hex, basename);
842	
843	    // Persist TOML first; if this fails, the sidecar never appeared on disk
844	    // at all. If it succeeds, we immediately persist the sidecar — under the
845	    // same exclusive lock there is no concurrent writer, and any reader
846	    // observing a mid-swap state lands on the consistent combinations
847	    // documented above.
848	    atomic_write(path, bytes)?;
849	    if let Err(e) = atomic_write(&sidecar, sidecar_contents.as_bytes()) {
850	        if integrity.strict {
851	            return Err(e).with_context(|| {
852	                format!(
853	                    "wrote {} but failed to refresh integrity sidecar (--strict-integrity was set, so this is a hard error)",
854	                    path.display()
855	                )
856	            });
857	        }
858	        eprintln!(
859	            "tomlctl: warning: wrote {} but failed to refresh integrity sidecar: {:#}",
860	            path.display(),
861	            e
862	        );
863	    }
864	    Ok(())
865	}
