868	/// Atomic-replace pattern: write `bytes` to a tempfile in the same directory as
869	/// `path`, `sync_all()` to flush to disk, then `persist()` to rename into place.
870	/// The `sync_all` call is load-bearing — without it, a crash between rename and
871	/// fsync can leave the target empty on some filesystems. See the tempfile crate
872	/// docs (`/stebalien/tempfile`) for the canonical pattern.
873	fn atomic_write(path: &Path, bytes: &[u8]) -> Result<()> {
874	    let parent = path
875	        .parent()
876	        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
877	        .unwrap_or(Path::new("."));
878	    let mut tmp = tempfile::NamedTempFile::new_in(parent)
879	        .with_context(|| format!("creating temp file in {}", parent.display()))?;
880	    tmp.as_file_mut()
881	        .write_all(bytes)
882	        .with_context(|| format!("writing temp file for {}", path.display()))?;
883	    tmp.as_file()
884	        .sync_all()
885	        .with_context(|| format!("fsync temp file for {}", path.display()))?;
886	    tmp.persist(path)
887	        .map_err(|e| anyhow!("atomic rename to {} failed: {}", path.display(), e.error))?;
888	    Ok(())
889	}
