900	/// Read-side access to a named array-of-tables. Returns an empty slice when
901	/// the array is missing or the value at that key isn't an array — symmetric
902	/// with `items_array_mut`, which auto-creates on write. R44: the previous
903	/// signature returned `Err(…)` on missing, which every caller had to
904	/// immediately translate into an empty-list fallback; inlining that policy
905	/// here removes five `match items_array { Err(_) => … }` tails.
906	fn items_array<'a>(doc: &'a TomlValue, name: &str) -> &'a [TomlValue] {
907	    static EMPTY: Vec<TomlValue> = Vec::new();
908	    doc.get(name)
909	        .and_then(|v| v.as_array())
910	        .map(Vec::as_slice)
911	        .unwrap_or(EMPTY.as_slice())
912	}
