914	fn items_array_mut<'a>(doc: &'a mut TomlValue, name: &str) -> Result<&'a mut Vec<TomlValue>> {
915	    let root = doc
916	        .as_table_mut()
917	        .ok_or_else(|| anyhow!("root is not a table"))?;
918	    let entry = root
919	        .entry(name.to_string())
920	        .or_insert_with(|| TomlValue::Array(Vec::new()));
921	    entry
