945	/// R57: array-parametric variant of `items_list`. Reads from the named
946	/// array-of-tables (default `items`). Filters apply uniformly — there's no
947	/// per-array filter-key policy, the same `ListFilters` shape is used.
948	fn items_list_from(
949	    doc: &TomlValue,
950	    array_name: &str,
951	    filters: ListFilters<'_>,
952	) -> Result<Vec<JsonValue>> {
953	    let items = items_array(doc, array_name);
954	    let mut out = Vec::new();
955	    for item in items {
956	        let Some(tbl) = item.as_table() else { continue };
957	        if let Some(want) = filters.status
958	            && str_field(tbl, "status") != want
959	        {
960	            continue;
961	        }
962	        if let Some(want) = filters.category
963	            && str_field(tbl, "category") != want
964	        {
965	            continue;
966	        }
967	        if let Some(want) = filters.file_filter
968	            && str_field(tbl, "file") != want
969	        {
970	            continue;
971	        }
972	        if let Some(threshold) = filters.newer_than {
973	            let Some(ff) = tbl.get("first_flagged").and_then(|v| v.as_datetime()) else {
974	                continue;
975	            };
976	            if !datetime_gt(ff, threshold) {
977	                continue;
978	            }
979	        }
980	        out.push(toml_to_json(item));
981	    }
982	    Ok(out)
983	}
