1089	/// Extended variant of `items_apply_to` honouring the `--no-remove` flag (R37).
1090	/// When `no_remove` is true, the batch is scanned up-front for any `remove` op;
1091	/// if present, the whole apply is refused — no partial mutation occurs because
1092	/// the check runs before the mutation loop.
1093	fn items_apply_to_opts(
1094	    doc: &mut TomlValue,
1095	    ops_json: &str,
1096	    array_name: &str,
1097	    no_remove: bool,
1098	) -> Result<()> {
1099	    let ops: JsonValue = serde_json::from_str(ops_json).context("parsing --ops")?;
1100	    let arr = ops
1101	        .as_array()
1102	        .ok_or_else(|| anyhow!("--ops must be a JSON array"))?;
1103	    if no_remove {
1104	        for (i, op) in arr.iter().enumerate() {
1105	            if op.get("op").and_then(|v| v.as_str()) == Some("remove") {
1106	                bail!(
1107	                    "op[{}] is a remove op, but --no-remove was set; this flag is used by review-apply/optimise-apply to prevent agent-generated payloads from erasing audit history",
1108	                    i
1109	                );
1110	            }
1111	        }
1112	    }
1113	    for (i, op) in arr.iter().enumerate() {
1114	        apply_single_op(doc, op, array_name).with_context(|| format!("op[{}] failed", i))?;
1115	    }
1116	    Ok(())
1117	}
