1119	fn apply_single_op(doc: &mut TomlValue, op: &JsonValue, array_name: &str) -> Result<()> {
1120	    let obj = op
1121	        .as_object()
1122	        .ok_or_else(|| anyhow!("op must be a JSON object"))?;
1123	    let op_name = obj
1124	        .get("op")
1125	        .and_then(|v| v.as_str())
1126	        .ok_or_else(|| anyhow!("op missing `op` field"))?;
1127	    match op_name {
1128	        "add" => {
1129	            let json = obj
1130	                .get("json")
1131	                .ok_or_else(|| anyhow!("add op missing `json` field"))?;
1132	            items_add_value_to(doc, json, array_name)
1133	        }
1134	        "update" => {
1135	            let id = obj
1136	                .get("id")
1137	                .and_then(|v| v.as_str())
1138	                .ok_or_else(|| anyhow!("update op missing `id` field"))?;
1139	            let json = obj
1140	                .get("json")
1141	                .ok_or_else(|| anyhow!("update op missing `json` field"))?;
1142	            let unset: Vec<String> = match obj.get("unset") {
1143	                None | Some(JsonValue::Null) => Vec::new(),
1144	                Some(JsonValue::Array(a)) => {
1145	                    let mut out = Vec::with_capacity(a.len());
1146	                    for (idx, entry) in a.iter().enumerate() {
1147	                        match entry {
1148	                            JsonValue::String(s) => out.push(s.clone()),
1149	                            // R36: report element type + index only; the value
1150	                            // itself may be agent-generated text and must not
1151	                            // land on stderr verbatim.
1152	                            other => bail!(
1153	                                "update op `unset` must be an array of strings, got {} at index {}",
1154	                                json_type_name(other),
1155	                                idx
1156	                            ),
1157	                        }
1158	                    }
1159	                    out
1160	                }
1161	                // R36: value suppressed — report only the JSON type.
1162	                Some(other) => bail!(
1163	                    "update op `unset` must be a JSON array of strings, got {}",
1164	                    json_type_name(other)
1165	                ),
1166	            };
1167	            // R57: update now honours the apply-op's --array parameter so a
1168	            // batch targeting e.g. `rollback_events` can update entries there,
1169	            // not just in `[[items]]`.
1170	            items_update_value_to(doc, array_name, id, json, &unset)
1171	        }
1172	        "remove" => {
1173	            let id = obj
1174	                .get("id")
1175	                .and_then(|v| v.as_str())
1176	                .ok_or_else(|| anyhow!("remove op missing `id` field"))?;
1177	            // R57: remove also follows the --array parameter.
1178	            items_remove_from(doc, array_name, id)
1179	        }
1180	        other => bail!("unknown op `{}`", other),
1181	    }
1182	}
