1200	fn items_next_id(doc: &TomlValue, prefix: &str) -> Result<String> {
1201	    if prefix.is_empty() {
1202	        bail!("prefix must not be empty — use a letter like R, O, or A");
1203	    }
1204	    if prefix.chars().all(|c| c.is_ascii_digit()) {
1205	        bail!("prefix must not be all-digit — would collide with numeric-suffix parsing");
1206	    }
1207	    let mut max_n: u64 = 0;
1208	    for item in items_array(doc, "items") {
1209	        if let Some(id) = item_id(item)
1210	            && let Some(rest) = id.strip_prefix(prefix)
1211	            && let Ok(n) = rest.parse::<u64>()
1212	            && n > max_n
1213	        {
1214	            max_n = n;
1215	        }
1216	    }
1217	    Ok(format!("{}{}", prefix, max_n + 1))
1218	}
