1225	    // missing) so the prior Err→empty fallback is gone.
1226	    let items: &[TomlValue] = items_array(doc, "items");
1227	    match tier {
1228	        DupTier::A => find_duplicates_tier_a(items),
1229	        DupTier::B => find_duplicates_tier_b(items),
