1234	fn dup_group_json(tier: &str, key: &str, items: &[&TomlValue]) -> JsonValue {
1235	    let mut obj = serde_json::Map::new();
1236	    obj.insert("tier".into(), JsonValue::String(tier.into()));
1237	    obj.insert("key".into(), JsonValue::String(key.into()));
1238	    obj.insert(
1239	        "items".into(),
1240	        JsonValue::Array(items.iter().map(|v| toml_to_json(v)).collect()),
1241	    );
