1245	fn find_duplicates_tier_a(items: &[TomlValue]) -> Result<Vec<JsonValue>> {
1246	    // Group under two key-spaces:
1247	    //   by (file, symbol) when symbol is non-empty
1248	    //   by (file, summary) otherwise
1249	    // An item appears in exactly one group (either symbol-keyed or summary-keyed).
1250	    let mut by_symbol: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
1251	    let mut by_summary: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
1252	    for (i, item) in items.iter().enumerate() {
1253	        let Some(tbl) = item.as_table() else { continue };
1254	        let file = str_field(tbl, "file");
1255	        let symbol = str_field(tbl, "symbol");
1256	        if !symbol.is_empty() {
1257	            by_symbol
1258	                .entry((file.to_string(), symbol.to_string()))
1259	                .or_default()
1260	                .push(i);
1261	        } else {
1262	            let summary = str_field(tbl, "summary");
1263	            by_summary
1264	                .entry((file.to_string(), summary.to_string()))
1265	                .or_default()
1266	                .push(i);
1267	        }
1268	    }
1269	    let mut out = Vec::new();
1270	    for ((file, symbol), idxs) in &by_symbol {
1271	        if idxs.len() < 2 {
1272	            continue;
1273	        }
1274	        let refs: Vec<&TomlValue> = idxs.iter().map(|&i| &items[i]).collect();
1275	        out.push(dup_group_json(
1276	            "A",
1277	            &format!("file={} symbol={}", file, symbol),
1278	            &refs,
1279	        ));
1280	    }
1281	    for ((file, summary), idxs) in &by_summary {
1282	        if idxs.len() < 2 {
1283	            continue;
1284	        }
1285	        let refs: Vec<&TomlValue> = idxs.iter().map(|&i| &items[i]).collect();
1286	        out.push(dup_group_json(
1287	            "A",
1288	            &format!("file={} summary={}", file, summary),
1289	            &refs,
1290	        ));
1291	    }
1292	    Ok(out)
1293	}
