1295	fn find_duplicates_tier_b(items: &[TomlValue]) -> Result<Vec<JsonValue>> {
1296	    let mut groups: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
1297	    for (i, item) in items.iter().enumerate() {
1298	        let Some(tbl) = item.as_table() else { continue };
1299	        let file = str_field(tbl, "file");
1300	        let summary = str_field(tbl, "summary");
1301	        let severity = str_field(tbl, "severity");
1302	        let category = str_field(tbl, "category");
1303	        let symbol = str_field(tbl, "symbol");
1304	        let canonical = format!(
1305	            "{}|{}|{}|{}|{}",
1306	            file, summary, severity, category, symbol
1307	        );
1308	        let full = hex_lower(&Sha256::digest(canonical.as_bytes()));
1309	        let short = full[..16].to_string();
1310	        let basename = Path::new(file)
1311	            .file_name()
1312	            .map(|s| s.to_string_lossy().into_owned())
1313	            .unwrap_or_else(|| file.to_string());
1314	        groups.entry((short, basename)).or_default().push(i);
1315	    }
1316	    let mut out = Vec::new();
1317	    for ((fingerprint, basename), idxs) in &groups {
1318	        if idxs.len() < 2 {
1319	            continue;
1320	        }
1321	        let refs: Vec<&TomlValue> = idxs.iter().map(|&i| &items[i]).collect();
1322	        out.push(dup_group_json(
1323	            "B",
1324	            &format!(
1325	                "suggestion fingerprint={} basename={}",
1326	                fingerprint, basename
1327	            ),
1328	            &refs,
1329	        ));
1330	    }
1331	    Ok(out)
1332	}
