1334	fn find_duplicates_tier_c(items: &[TomlValue]) -> Result<Vec<JsonValue>> {
1335	    // Candidates: items with empty/missing symbol AND line > 0.
1336	    #[derive(Clone)]
1337	    struct Candidate {
1338	        idx: usize,
1339	        file: String,
1340	        line: i64,
1341	    }
1342	    let mut by_file: HashMap<String, Vec<Candidate>> = HashMap::new();
1343	    for (i, item) in items.iter().enumerate() {
1344	        let Some(tbl) = item.as_table() else { continue };
1345	        let symbol = str_field(tbl, "symbol");
1346	        if !symbol.is_empty() {
1347	            continue;
1348	        }
1349	        let line = i64_field(tbl, "line");
1350	        if line <= 0 {
1351	            continue;
1352	        }
1353	        let file = str_field(tbl, "file").to_string();
1354	        by_file.entry(file.clone()).or_default().push(Candidate {
1355	            idx: i,
1356	            file,
1357	            line,
1358	        });
1359	    }
1360	
1361	    let mut out = Vec::new();
1362	    // Deterministic order: sort file keys.
1363	    let mut files: Vec<&String> = by_file.keys().collect();
1364	    files.sort();
1365	    for file in files {
1366	        let cands = &by_file[file];
1367	        // Sort by line then idx so sweep is deterministic.
1368	        // R26: `to_vec()` (clippy-preferred over `iter().cloned().collect()`)
1369	        // replaces the previous wholesale `cands.clone()` with the same
1370	        // semantics — we still need a mutable owned Vec for in-place sort,
1371	        // but without borrowing `by_file` mutably while iterating its keys.
1372	        let mut sorted: Vec<Candidate> = cands.to_vec();
1373	        sorted.sort_by(|a, b| a.line.cmp(&b.line).then(a.idx.cmp(&b.idx)));
1374	        let n = sorted.len();
1375	        let mut i = 0;
1376	        while i < n {
1377	            // Greedy: start a group at sorted[i], extend while every pair in
1378	            // the growing group satisfies |line_a - line_b| <= 10. Because
1379	            // items are sorted by line, the tightest constraint is between
1380	            // the group's min-line (sorted[i]) and the candidate's line.
1381	            let mut j = i + 1;
1382	            while j < n && sorted[j].line - sorted[i].line <= 10 {
1383	                j += 1;
1384	            }
1385	            if j - i >= 2 {
1386	                let refs: Vec<&TomlValue> = sorted[i..j].iter().map(|c| &items[c.idx]).collect();
1387	                out.push(dup_group_json(
1388	                    "C",
1389	                    &format!(
1390	                        "file={} line_window=[{}..{}]",
1391	                        sorted[i].file, sorted[i].line, sorted[j - 1].line
1392	                    ),
1393	                    &refs,
1394	                ));
1395	                i = j;
1396	            } else {
1397	                i += 1;
1398	            }

1399	        }
1400	    }
1401	    Ok(out)
1402	}
