1405	
1406	fn items_orphans(doc: &TomlValue) -> Result<Vec<JsonValue>> {
1407	    // R44: items_array returns an empty slice when missing, so the early-return
1408	    // on error disappears — an empty ledger naturally produces zero orphans.
1409	    let items = items_array(doc, "items");
1410	
1411	    // Build set of known IDs for dangling-dep check.
1412	    let mut known_ids: HashSet<String> = HashSet::new();
1413	    for item in items {
1414	        if let Some(id) = item_id(item) {
1415	            known_ids.insert(id.to_string());
1416	        }
1417	    }
1418	
1419	    let root = repo_or_cwd_root()?;
1420	
1421	    let mut out = Vec::new();
1422	    for item in items {
1423	        let Some(tbl) = item.as_table() else { continue };
1424	        let id = str_field(tbl, "id");
1425	        let file = str_field(tbl, "file");
1426	        let symbol = str_field(tbl, "symbol");
1427	
1428	        // missing-file / symbol-missing classes (mutually exclusive: the first
1429	        // failing check wins).
1430	        if !file.is_empty() {
1431	            let resolved = resolve_relative_to_root(&root, file);
1432	            // R38: a RELATIVE ledger-item `file` field that escapes the root
1433	            // via `..` (e.g. `../../etc/passwd`) turns `fs::read_to_string`
1434	            // into an existence/symbol-presence oracle on arbitrary host
1435	            // paths. Canonicalise and assert containment for relative inputs
1436	            // only — absolute inputs are treated as intentional opt-in by
1437	            // the ledger author (this matches the pre-R38 behaviour on the
1438	            // happy path).
1439	            let is_relative = !Path::new(file).is_absolute();
1440	            let contained = if is_relative {
1441	                match (resolved.canonicalize().ok(), root.canonicalize().ok()) {
1442	                    (Some(c), Some(r)) => c.starts_with(&r),
1443	                    (Some(c), None) => c.starts_with(&root),
1444	                    (None, _) => true, // missing target falls through to `missing-file`.
1445	                }
1446	            } else {
1447	                true
1448	            };
1449	            if !contained {
1450	                let mut obj = serde_json::Map::new();
1451	                obj.insert("id".into(), JsonValue::String(id.into()));
1452	                obj.insert("class".into(), JsonValue::String("outside-repo".into()));
1453	                obj.insert("file".into(), JsonValue::String(file.into()));
1454	                out.push(JsonValue::Object(obj));
1455	            } else if !resolved.exists() {
1456	                let mut obj = serde_json::Map::new();
1457	                obj.insert("id".into(), JsonValue::String(id.into()));
1458	                obj.insert("class".into(), JsonValue::String("missing-file".into()));
1459	                obj.insert("file".into(), JsonValue::String(file.into()));
1460	                out.push(JsonValue::Object(obj));
1461	            } else if !symbol.is_empty() {
1462	                // R27: explicit match — IO errors surface as an `io-error`
1463	                // orphan instead of silently treating the file as empty
1464	                // (which would fire `symbol-missing` spuriously for
1465	                // unreadable-but-existing files).
1466	                match fs::read_to_string(&resolved) {
1467	                    Ok(contents) => {
1468	                        if !contents.contains(symbol) {
1469	                            let mut obj = serde_json::Map::new();
1470	                            obj.insert("id".into(), JsonValue::String(id.into()));
1471	                            obj.insert("class".into(), JsonValue::String("symbol-missing".into()));
1472	                            obj.insert("file".into(), JsonValue::String(file.into()));
1473	                            obj.insert("symbol".into(), JsonValue::String(symbol.into()));
1474	                            out.push(JsonValue::Object(obj));
1475	                        }
1476	                    }
1477	                    Err(_) => {
1478	                        let mut obj = serde_json::Map::new();
1479	                        obj.insert("id".into(), JsonValue::String(id.into()));
1480	                        obj.insert("class".into(), JsonValue::String("io-error".into()));
1481	                        obj.insert("file".into(), JsonValue::String(file.into()));
1482	                        out.push(JsonValue::Object(obj));
1483	                    }
1484	                }
1485	            }
1486	        }
1487	
1488	        // dangling-dep class (independent of the file/symbol axis; an item can
1489	        // be orphaned in both ways and will surface twice).
1490	        if let Some(deps) = tbl.get("depends_on").and_then(|v| v.as_array()) {
1491	            let mut missing: Vec<String> = Vec::new();
1492	            for dep in deps {
1493	                if let Some(d) = dep.as_str()
1494	                    && !known_ids.contains(d)
1495	                {
1496	                    missing.push(d.to_string());
1497	                }
1498	            }
1499	            if !missing.is_empty() {
1500	                let mut obj = serde_json::Map::new();
1501	                obj.insert("id".into(), JsonValue::String(id.into()));
1502	                obj.insert("class".into(), JsonValue::String("dangling-dep".into()));
1503	                obj.insert(
1504	                    "dangling_deps".into(),
1505	                    JsonValue::Array(missing.into_iter().map(JsonValue::String).collect()),
1506	                );
1507	                out.push(JsonValue::Object(obj));
1508	            }
1509	        }
1510	    }
1511	    Ok(out)
1512	}
