1890	        let pos = bytes.iter().position(|&b| b == b'R').unwrap();
1891	        bytes[pos] = b'Q';
1892	        fs::write(&target, &bytes).unwrap();
1893	        let err = verify_integrity(&target).unwrap_err();
1894	        let msg = format!("{err:#}");
1895	        assert!(
1896	            msg.contains("expected") && msg.contains("actual"),
1897	            "expected dual-digest message, got: {msg}"
1898	        );

