1958	    fn blocks_verify_detects_drift() {
1959	        let dir = tempfile::tempdir().unwrap();
1960	        let a = dir.path().join("a.md");
1961	        let b = dir.path().join("b.md");
1962	        let good = "\
1963	<!-- SHARED-BLOCK:flow-context START -->
