1971	            blocks_verify(&[a.clone(), b.clone()], &["flow-context".to_string()]).unwrap();
1972	        assert!(report.ok, "equal content must be ok");
1973	
1974	        let drifted = "\
1975	<!-- SHARED-BLOCK:flow-context START -->
1976	line one
1977	DIFFERENT
1978	<!-- SHARED-BLOCK:flow-context END -->
1979	";
1980	        fs::write(&b, drifted).unwrap();
1981	        let report = blocks_verify(&[a, b], &["flow-context".to_string()]).unwrap();
1982	        assert!(!report.ok);
1983	        // drift entries carry per-file hash detail
1984	        let blocks = report.report.get("blocks").and_then(|v| v.as_array()).unwrap();
1985	        assert_eq!(blocks.len(), 1);
1986	        let drift_arr = blocks[0].get("drift").and_then(|v| v.as_array()).unwrap();
1987	        assert_eq!(drift_arr.len(), 2);
