fn read_toml(path: &Path) -> Result<TomlValue> {
    let s = fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
    toml::from_str::<TomlValue>(&s).with_context(|| format!("parsing {}", path.display()))
